        static string PreviewText(string en)
        {
            LanguageOption option = FindLanguage(Language);
            if (option == null || !option.Preview || en == null) return null;
            string[] values;
            return PreviewCatalog.TryGetValue(en, out values) ? values[option.PreviewIndex] : null;
        }
    }
